<?php
/** Slice 6 — count sheets (counts.md "Proof": Sheets): make, fill from the shelves, add, reorder (the drag's POST, ▲/▼ without JavaScript), remove, units, walls. */
require __DIR__ . '/lib.php';
$w = count_world();
$bea = person(28); $dana = person(30); $ann = person(29); $marcoA = person(27, AIRPORT);

echo "1. The list and who may make a sheet\n";
$r = page($dana, '/counts/sheets/');
ok($r['code'] === 200 && has($r, 'data-screen="count-sheet-list"') && has($r, 'id="sheet-form"') && has($r, 'id="count-sheet-list-empty"'), 'Dana (Chef) opens the list: the form to make a sheet, and the empty state in words');
$r = page($bea, '/counts/sheets/');
ok($r['code'] === 200 && !has($r, 'id="sheet-form"'), 'Bea (Kitchen) reads the list (ri.read) and has no form to make a sheet');
ok(page($ann, '/counts/sheets/')['code'] === 200, 'Ann (Viewer) reads it too');
$r = post($bea, '/counts/sheets/save.php', ['name' => 'Bea sheet']);
ok($r['code'] === 403 && says($r, 'does not let you'), 'Bea making a sheet: 403 in words (no ingredients.write)');

echo "2. Dana makes Full house, filled from the shelves\n";
$before = last_activity_id();
$r = post($dana, '/counts/sheets/save.php', ['name' => 'Full house', 'kind' => 'full', 'fill' => 'yes']);
$sid = last_id('count_sheets');
ok($r['code'] === 302 && preg_match('#^/counts/sheets/' . $sid . '\?notice=created#', $r['location']) === 1, 'count_sheet_save lands on the sheet');
$lines = q('SELECT l.*, a.name AS area FROM count_sheet_lines l JOIN storage_areas a ON a.id = l.storage_area_id WHERE l.sheet_id = :s ORDER BY a.walk_order, l.shelf_order', ['s' => $sid]);
ok(count($lines) === 6, 'fill: a line for every ingredient with a balance in every area (6): ' . implode(', ', array_map(fn ($l) => $l['area'] . '/' . $l['ingredient_id'], $lines)));
ok(sheet_order($sid, $w['walkin']) === [$w['egg'], $w['oil']] && sheet_order($sid, $w['dry']) === [$w['flour']] && sheet_order($sid, $w['bar']) === [$w['gin'], $w['lime']] && sheet_order($sid, $w['cold']) === [$w['chicken']], 'shelf order by name within each area');
ok(one('SELECT count_unit_code FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i', ['s' => $sid, 'i' => $w['flour']]) === 'bag50' && one('SELECT count_unit_code FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i', ['s' => $sid, 'i' => $w['chicken']]) === null, 'each line carries the default count unit where the ingredient has one (flour bag50), else null (chicken)');
$a = activity('count_sheet.save', $before);
ok(count($a) === 1 && json_decode($a[0]['after'], true)['fill'] === true && json_decode($a[0]['after'], true)['lines'] === 6 && (int) $a[0]['scope_id'] === DOWNTOWN, 'count_sheet.save logged with fill, lines and the site');
$h = page($dana, "/counts/sheets/$sid");
preg_match_all('/id="sheet-area-(\d+)"/', $h['body'], $m);
ok($h['code'] === 200 && array_slice(array_map('intval', $m[1]), 0, 4) === [$w['walkin'], $w['dry'], $w['bar'], $w['cold']], 'the sheet page lists the areas in walk order');
ok(has($h, 'data-screen="count-sheet-edit"') && has($h, 'data-entity="count_sheet"') && has($h, 'id="sheet-add-form-' . $w['bar'] . '"') && has($h, 'id="sheet-fill"') && has($h, 'id="sheet-start-count-btn"'), 'ids: the add form per area, Fill from the shelves, Start a count from this sheet');
$egg = (int) one('SELECT id FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i', ['s' => $sid, 'i' => $w['egg']]);
$oil = (int) one('SELECT id FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i', ['s' => $sid, 'i' => $w['oil']]);
ok(has($h, 'id="sheet-line-' . $egg . '"') && has($h, 'id="sheet-line-' . $egg . '-up"') && has($h, 'id="sheet-line-' . $egg . '-down"') && has($h, 'id="sheet-line-' . $egg . '-remove"') && has($h, 'class="sheet-handle'), 'a line: its unit, ▲/▼ (the no-JavaScript way), Remove and the drag handle');

echo "3. Adding a line\n";
$before = last_activity_id();
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['walkin'], 'ingredient' => $w['lime'], 'count_unit' => 'each']);
$limeLine = (int) one('SELECT id FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i AND storage_area_id = :a', ['s' => $sid, 'i' => $w['lime'], 'a' => $w['walkin']]);
ok($r['code'] === 302 && $limeLine > 0 && one('SELECT count_unit_code FROM count_sheet_lines WHERE id = :i', ['i' => $limeLine]) === 'each' && (int) one('SELECT shelf_order FROM count_sheet_lines WHERE id = :i', ['i' => $limeLine]) === 3, 'limes added to the Walk-in counted in each, at the end of the shelf');
$a = activity('count_sheet.line_set', $before);
ok(count($a) === 1 && (int) $a[0]['ingredient_id'] === $w['lime'], 'count_sheet.line_set logged with ingredient_id');
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['walkin'], 'ingredient' => $w['lime']]);
ok($r['code'] === 422 && says($r, 'already on this sheet in that area'), 'the same ingredient twice in one area: the unique, in words');
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['dry'], 'ingredient' => $w['egg'], 'count_unit' => 'ml']);
ok($r['code'] === 422 && says($r, 'no each-volume'), 'a unit the ingredient cannot convert (eggs in ml): the database\'s sentence');
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['dry'], 'ingredient' => $w['egg'], 'count_unit' => 'zzz']);
ok($r['code'] === 422 && says($r, 'No unit zzz'), 'an unknown unit: "No unit zzz for …"');
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['dry']]);
ok($r['code'] === 422 && says($r, 'Choose the ingredient'), 'no ingredient: asked for');
$r = post($bea, '/counts/sheets/line.php', ['sheet' => $sid, 'area' => $w['dry'], 'ingredient' => $w['egg']]);
ok($r['code'] === 403, 'Bea adding a line: 403');
$r = post($dana, '/counts/sheets/line.php', ['sheet' => $sid, 'sheet_line' => $limeLine, 'count_unit' => ''], ['HX-Request: true']);
ok($r['code'] === 200 && has($r, 'id="sheet-line-' . $limeLine . '"') && has($r, 'id="sheet-line-' . $limeLine . '-saved"') && one('SELECT count_unit_code FROM count_sheet_lines WHERE id = :i', ['i' => $limeLine]) === null, 'changing a line\'s unit answers its row (Pattern C) and "saved"; empty is the default again');

echo "4. Removing and reordering\n";
$before = last_activity_id();
$r = post($dana, '/counts/sheets/line-remove.php', ['sheet_line' => $limeLine]);
ok($r['code'] === 302 && (int) one('SELECT count(*) FROM count_sheet_lines WHERE id = :i', ['i' => $limeLine]) === 0 && count(activity('count_sheet.line_remove', $before)) === 1, 'Remove deletes the line and logs it');
$r = post($dana, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => [$oil, $egg]]);
ok($r['code'] === 302 && sheet_order($sid, $w['walkin']) === [$w['oil'], $w['egg']], 'the reorder POST (lines[] as the drag sends them) renumbers the shelf: oil then eggs');
$a = activity('count_sheet.reorder', $before);
ok(count($a) === 1 && json_decode($a[0]['after'], true)['lines'] === [$oil, $egg], 'count_sheet.reorder logged with the ids in order');
$r = post($dana, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => [$egg, $oil]], ['HX-Request: true']);
ok($r['code'] === 204 && sheet_order($sid, $w['walkin']) === [$w['egg'], $w['oil']], 'an HTMX reorder answers 204 and saves');
$h = page($dana, "/counts/sheets/$sid");
$down = move_lines($h['body'], 'sheet-line-' . $egg . '-down');
ok($down === [$oil, $egg], '▼ on eggs carries the moved order (oil, eggs) in its hidden lines[]');
$r = post($dana, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => $down]);
ok($r['code'] === 302 && sheet_order($sid, $w['walkin']) === [$w['oil'], $w['egg']] && str_contains($r['location'], '#sheet-area-' . $w['walkin']), '…and posting it (no JavaScript) reorders and lands back on the area');
$r = post_json($dana, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => "$egg,$oil"]);
ok($r['code'] === 200 && ($r['json']['ok'] ?? false) === true && sheet_order($sid, $w['walkin']) === [$w['egg'], $w['oil']], 'JSON: lines as a comma list; ok');
$r = post($dana, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => [$egg, (int) one('SELECT id FROM count_sheet_lines WHERE sheet_id = :s AND ingredient_id = :i', ['s' => $sid, 'i' => $w['gin']])]]);
ok($r['code'] === 422 && says($r, 'is not on this sheet in that area'), 'a line of another area: refused in words');
ok(post($bea, '/counts/sheets/reorder.php', ['sheet' => $sid, 'area' => $w['walkin'], 'lines' => [$oil, $egg]])['code'] === 403, 'Bea reordering: 403');

echo "5. Names, kinds, archive, walls\n";
$r = post($dana, '/counts/sheets/save.php', ['name' => 'Full house']);
ok($r['code'] === 422 && says($r, 'A sheet named Full house exists at this site'), 'a second sheet with the same name: the unique, in words');
ok(post($dana, '/counts/sheets/save.php', ['name' => str_repeat('x', 81)])['code'] === 422 && post($dana, '/counts/sheets/save.php', ['name' => 'Odd', 'kind' => 'weekly'])['code'] === 422, 'a name over 80 characters and an unknown kind are refused');
$r = post($dana, '/counts/sheets/save.php', ['name' => 'Bar spot', 'kind' => 'spot']);
$bar = last_id('count_sheets');
ok($r['code'] === 302 && one('SELECT kind FROM count_sheets WHERE id = :i', ['i' => $bar]) === 'spot' && (int) one('SELECT count(*) FROM count_sheet_lines WHERE sheet_id = :s', ['s' => $bar]) === 0, 'a spot sheet with no fill starts empty');
$r = post($dana, '/counts/sheets/save.php', ['sheet' => $bar, 'active' => 'no']);
$l = page($dana, '/counts/sheets/')['body'];
ok($r['code'] === 302 && has(['body' => $l], 'id="sheet-card-' . $bar . '"') && str_contains($l, 'archived') && !str_contains(page($bea, '/counts/sheets/')['body'], 'id="sheet-card-' . $bar . '"'), 'an archived sheet is a dark card for the Chef and hidden from the Kitchen');
$cardFull = page($bea, '/counts/sheets/')['body'];
ok(str_contains($cardFull, 'id="sheet-card-' . $sid . '"') && str_contains($cardFull, '6 lines in 4 areas') && str_contains($cardFull, 'No count made from it yet') && str_contains($cardFull, 'id="sheet-card-' . $sid . '-start"'), 'the card: lines, areas, the last count, Start a count');
$r = req('GET', "/counts/sheets/$sid", ['jar' => $marcoA]);
ok($r['code'] === 404, 'Marco signed on at Airport: a Downtown sheet is a 404');
$j = get_json($dana, "/counts/sheets/$sid");
ok(($j['json']['data']['sheet']['name'] ?? '') === 'Full house' && count($j['json']['data']['sheet']['areas'] ?? []) >= 4 && isset($j['json']['data']['sheet']['areas'][0]['lines'][0]['sheet_line_id']), 'JSON: the sheet with its areas and lines');
ok(post($dana, '/counts/sheets/save.php', ['sheet' => $bar, 'active' => 'yes'])['code'] === 302, 'the spot sheet is back in use');
finish();
